CREATE DATABASE IF NOT EXISTS sunog_kilay_emc CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sunog_kilay_emc;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','teacher','student') NOT NULL,is_active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE users ADD COLUMN IF NOT EXISTS last_name VARCHAR(80), ADD COLUMN IF NOT EXISTS first_name VARCHAR(80), ADD COLUMN IF NOT EXISTS middle_name VARCHAR(80), ADD COLUMN IF NOT EXISTS name_extension VARCHAR(20);
CREATE TABLE IF NOT EXISTS professors(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,last_name VARCHAR(80),first_name VARCHAR(80),middle_name VARCHAR(80),name_extension VARCHAR(20),email VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
ALTER TABLE professors ADD COLUMN IF NOT EXISTS last_name VARCHAR(80), ADD COLUMN IF NOT EXISTS first_name VARCHAR(80), ADD COLUMN IF NOT EXISTS middle_name VARCHAR(80), ADD COLUMN IF NOT EXISTS name_extension VARCHAR(20);
CREATE TABLE IF NOT EXISTS courses(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT,subject_code VARCHAR(40),subject_description TEXT,units DECIMAL(4,1),schedule_date DATE,schedule_time TIME,teacher_id INT NULL,professor_id INT NULL,FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(professor_id) REFERENCES professors(id) ON DELETE SET NULL);
ALTER TABLE courses ADD COLUMN IF NOT EXISTS subject_code VARCHAR(40), ADD COLUMN IF NOT EXISTS subject_description TEXT, ADD COLUMN IF NOT EXISTS units DECIMAL(4,1), ADD COLUMN IF NOT EXISTS schedule_date DATE, ADD COLUMN IF NOT EXISTS schedule_time TIME, ADD COLUMN IF NOT EXISTS schedule_days VARCHAR(40), ADD COLUMN IF NOT EXISTS schedule_times VARCHAR(255);
ALTER TABLE courses MODIFY teacher_id INT NULL, ADD COLUMN IF NOT EXISTS professor_id INT NULL;
UPDATE courses SET subject_code=title WHERE subject_code IS NULL OR subject_code='';
UPDATE courses SET subject_description=description WHERE subject_description IS NULL;
CREATE TABLE IF NOT EXISTS enrollments(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,student_id INT NOT NULL,UNIQUE(course_id,student_id),FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,teacher_id INT NOT NULL,title VARCHAR(180),body TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS assignments(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,teacher_id INT NOT NULL,title VARCHAR(180),instructions TEXT,due_date DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS materials(id INT AUTO_INCREMENT PRIMARY KEY,course_id INT NOT NULL,teacher_id INT NOT NULL,original_name VARCHAR(255),stored_name VARCHAR(255),mime_type VARCHAR(120),file_size BIGINT,uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE,FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS submissions(id INT AUTO_INCREMENT PRIMARY KEY,assignment_id INT NOT NULL,student_id INT NOT NULL,response_text TEXT,original_name VARCHAR(255),stored_name VARCHAR(255),mime_type VARCHAR(120),file_size BIGINT,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
